    private static void wireName(DataOutputStream out,List<String> labels)throws Exception{
        for(String label:labels){byte[] bytes=label.getBytes("UTF-8");out.writeByte(bytes.length);out.write(bytes);}out.writeByte(0);
    }
    private static void wireRecord(DataOutputStream out,List<String> owner,int kind,long ttl,byte[] value)throws Exception{
        wireName(out,owner);out.writeShort(kind);out.writeShort(0x8001);out.writeInt((int)ttl);out.writeShort(value.length);out.write(value);
    }
    private static byte[] txtWire(String instance,String type,long ttl,String... attributes)throws Exception{
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeShort(0);out.writeShort(0x8400);out.writeShort(0);out.writeShort(1);out.writeInt(0);
        ByteArrayOutputStream txt=new ByteArrayOutputStream();for(String attribute:attributes){byte[] value=attribute.getBytes("UTF-8");txt.write(value.length);txt.write(value);}
        List<String> owner=new ArrayList<>();owner.add(instance);owner.addAll(Arrays.asList((type+"local").split("\\.")));wireRecord(out,owner,16,ttl,txt.toByteArray());return bytes.toByteArray();
    }
