    private static String wsReply(String discovery,String addressing,String id,String peer,String name){
        return "<s:Envelope xmlns:s='http://www.w3.org/2003/05/soap-envelope' xmlns:a='"+addressing+"' xmlns:d='"+discovery+"'><s:Header><a:Action>"+discovery+"/ProbeMatches</a:Action><a:RelatesTo>"+id+"</a:RelatesTo></s:Header><s:Body><d:ProbeMatches><d:ProbeMatch><a:EndpointReference><a:Address>urn:uuid:eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee</a:Address></a:EndpointReference><d:Types xmlns:p='http://schemas.microsoft.com/windows/2006/08/wdp/print'>p:PrintDeviceType</d:Types><d:Scopes>onvif://www.onvif.org/name/"+name+" onvif://www.onvif.org/hardware/Fixture%20hardware onvif://www.onvif.org/MacAddress/00-11-22-33-44-55 onvif://www.onvif.org/location/private</d:Scopes><d:XAddrs>http://"+peer+":8899/device</d:XAddrs><d:MetadataVersion>1</d:MetadataVersion></d:ProbeMatch></d:ProbeMatches></s:Body></s:Envelope>";
    }
