        List<Device> fixture=new ArrayList<>();for(int n=1;n<=45;n++){Device d=new Device();d.ip="192.0.2."+n;d.name=String.format(Locale.ROOT,"Test device %02d",n);d.model=n%3==0?"Fixture model":"";d.lastSeen=System.currentTimeMillis();fixture.add(d);}
        Map<String,String> sources=new LinkedHashMap<>();sources.put("mDNS fixture","Truncated: unresolved service");sources.put("IPv4 checks","OK");
        ScanReport report=new ScanReport("192.0.2.0/24",false,"One source was truncated.",254,254,System.currentTimeMillis(),sources);store.retainIfCurrent(store.token(),live.key,fixture,report);
        activity=launch(false);waitForIdleSync();capture("hierarchy-light");assertText("Partial scan");assertText("45 device groups · 45 IPs");
        check(!texts().contains("Checked 254")&&!texts().contains("One source was truncated."),"Technical coverage stays out of the main list");
