        AccessibilityNodeInfo dialog=waitForDialog("192.0.2.0/24");Bitmap dialogImage=getUiAutomation().takeScreenshot();if(dialogImage!=null)save(dialogImage,"hierarchy-scan-details");check(dialog!=null&&!dialog.findAccessibilityNodeInfosByText("192.0.2.0/24").isEmpty(),"Full range is available in scan details");check(!dialog.findAccessibilityNodeInfosByText("254 / 254").isEmpty(),"Full coverage is available in scan details");check(!dialog.findAccessibilityNodeInfosByText("What may be missing").isEmpty(),"Incomplete source is explained before technical details");dialogClick("Show method details (2)");check(dialogTexts().contains("Truncated: unresolved service"),"Exact incomplete source reason remains available after expansion");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();
        final int[] offset={0};onMain(()->{View item=((Map<String,View>)field("deviceRows")).get("192.0.2.25");ScrollView page=(ScrollView)field("deviceScroll");page.scrollBy(0,top(item)-top(page)-120);});waitForIdleSync();capture("navigation-before-details");
        onMain(()->offset[0]=rowOffset("192.0.2.25"));click("Test device 25");assertText("Device details");description("Back to devices");settle();onMain(()->check(Math.abs(rowOffset("192.0.2.25")-offset[0])<=2,"Toolbar Back restores the selected row at its original offset"));capture("navigation-return-arrow");
        click("Test device 25");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);settle();onMain(()->check(Math.abs(rowOffset("192.0.2.25")-offset[0])<=2,"Android Back restores the selected row at its original offset"));
        click("Test device 25");onMain(()->{for(Device d:(List<Device>)field("devices"))if(Integer.parseInt(d.ip.substring(d.ip.lastIndexOf('.')+1))<25)d.model="Newly discovered details that make this row taller";});description("Back to devices");settle();onMain(()->check(Math.abs(rowOffset("192.0.2.25")-offset[0])<=2,"Changing row heights above the selection does not move the return target"));
        description("Switch to dark mode");settle();onMain(()->check(Math.abs(rowOffset("192.0.2.25")-offset[0])<=2,"Appearance change preserves the visible row"));capture("navigation-return-dark");
        setSearch("Test device 2");onMain(()->{ScrollView page=(ScrollView)field("deviceScroll");page.scrollTo(0,400);});settle();onMain(()->offset[0]=rowOffset("192.0.2.25"));click("Test device 25");description("Back to devices");settle();onMain(()->check(Math.abs(rowOffset("192.0.2.25")-offset[0])<=2,"Filtered list restores its selected row"));check(texts().contains("Test device 2")&&!texts().contains("Test device 01"),"Search query and filtering survive Back");
        setSearch("");onMain(()->check(((ScrollView)field("deviceScroll")).getScrollY()==0,"Changing search starts at the first matching device"));
        onMain(()->{Configuration c=new Configuration(activity.getResources().getConfiguration());c.fontScale=2;activity.getResources().updateConfiguration(c,activity.getResources().getDisplayMetrics());invoke("render");});settle();capture("hierarchy-dark-large-text");onMain(()->check(((ScrollView)field("deviceScroll")).getChildAt(0).getHeight()>((ScrollView)field("deviceScroll")).getHeight(),"Large text remains fully scrollable"));
        onMain(()->{Configuration c=new Configuration(activity.getResources().getConfiguration());c.fontScale=1;activity.getResources().updateConfiguration(c,activity.getResources().getDisplayMetrics());setField("demo",false);invoke("loadNetwork");invoke("resetListPosition");invoke("render");});description("Switch to light mode");settle();
