    private void failureReporting()throws Exception{
        Context target=getTargetContext();Store store=new Store(target);store.clear();store.dark(false);NetworkState live=NetworkState.current(target);
        DiscoveryHealth health=new DiscoveryHealth();String source="mDNS _hap._tcp.";
        health.resolving("fixture", "_hap._tcp.");health.resolveFailed("fixture", "No usable service data after 4002 ms (registered; no addresses)");
        health.fail(source,"First attempt: No usable service data after 4001 ms (registered; no addresses)");
        for(String event:new String[]{"failed","found","live service records","resolved","retried","timeout attempts"}){health.count(source,event);health.count(source,event);}
        String full=health.sources().get(source);check(full.length()>200&&full.length()<512,"Real two-attempt error plus six counters reproduces the old report overflow");
        Map<String,String> sources=new LinkedHashMap<>(health.sources());sources.put("mDNS _http._tcp.",full);sources.put("mDNS _fixture-unknown._tcp.","Truncated · Controlled fixture window ended");
        ScanReport report=new ScanReport("Fixture coverage",false,"Device details are partial: 2 discovery sources failed, 1 truncated. Tap scan status for details.",254,254,System.currentTimeMillis(),sources);
        check(report.sources.get(source).equals(full)&&report.sources.get(source).endsWith("timeout attempts 2"),"Terminal report preserves both native timeout reasons and all trailing counters");
        check(ScanReport.from(report.json()).sources.get(source).equals(full),"JSON round trip preserves the same bounded diagnostic value");
        Map<String,String> oversized=new LinkedHashMap<>();StringBuilder longValue=new StringBuilder("Failed · ");for(int i=0;i<1000;i++)longValue.append('x');oversized.put(source,longValue.toString());
        check(new ScanReport("",false,"",0,0,1,oversized).sources.get(source).length()==512,"Untrusted overlong source values remain capped");
        check(store.retainIfCurrent(store.token(),live.key,Collections.emptyList(),report),"Failure fixture retains a report without inventing devices");
        activity=launch(false);settle();onMain(()->invoke("scanDetails"));settle();String text=dialogTexts();
        check(text.contains("Needs attention: HomeKit accessories, Web services and 1 other method"),"Summary names affected methods and limits the list with readable singular wording");
        check(text.contains("Partial scan")&&!text.contains("timeout attempts 2"),"Named summary preserves Partial status and keeps raw diagnostics collapsed");
        assertModalFits();captureDialog("scan-details-failure-reporting-light");dialogClick("Show method details (3)");
        check(dialogTexts().contains(full)&&dialogTexts().contains("_fixture-unknown._tcp."),"Expanded method details expose the complete timeout evidence and unknown service type");
        dialogClick("Done");description("Switch to dark mode");onMain(()->invoke("scanDetails"));settle();
        check(dialogTexts().contains("Needs attention: HomeKit accessories, Web services and 1 other method"),"Dark appearance retains the same failure summary");assertModalFits();captureDialog("scan-details-failure-reporting-dark");dialogClick("Done");
        onMain(()->{Configuration config=new Configuration(activity.getResources().getConfiguration());config.fontScale=2;activity.getResources().updateConfiguration(config,activity.getResources().getDisplayMetrics());invoke("render");invoke("scanDetails");});settle();assertModalFits();captureDialog("scan-details-failure-reporting-large-text");
        dialogClick("Show method details (3)");check(dialogTexts().contains(full),"Large text retains full diagnostics in scrollable method details");dialogClick("Done");
        Map<String,String> ok=new LinkedHashMap<>();ok.put("IPv4 checks","OK");ok.put("IPv6 service checks","Not used · No separate IPv6 echo checks were needed");store.retainIfCurrent(store.token(),live.key,Collections.emptyList(),new ScanReport("Fixture coverage",true,"",254,254,System.currentTimeMillis(),ok));
        onMain(()->{invoke("loadNetwork");invoke("render");invoke("scanDetails");});settle();check(dialogTexts().contains("Complete scan")&&!dialogTexts().contains("Needs attention:"),"A subsequent successful current scan does not retain a previous failure summary");dialogClick("Show method details (2)");check(dialogTexts().contains("IPv6 replies received by other discovery methods can still appear")&&!dialogTexts().contains("No usable advertised IPv6"),"An unused extra-echo method does not imply IPv6 devices were absent");dialogClick("Done");onMain(()->activity.finish());
    }
