        description("Options");onMain(()->{PopupWindow popup=(PopupWindow)field("optionsMenu");check(find(popup.getContentView(),"Delete saved data",false)==null,"The main menu has no delete action");});menuChoose("Settings");settingsClick("Privacy & device details");check(optionTexts().contains("Session-only results")&&optionTexts().contains("no scan files"),"Privacy explains the session-only policy");optionClick("Done");settingsClick("Clear current results");check(optionTexts().contains("no saved history"),"Memory reset explains its scope");optionClick("Cancel");check(store.devices(live.key).size()==1&&store.dark()==!system,"Cancelling keeps the list and appearance");
