    private void scanCheck(Context target,NetworkState live,String range,String expected,boolean self)throws Exception{
        CountDownLatch finished=new CountDownLatch(1);final List<Device>[] result=new List[]{null};final String[] summary={""};
        new Discovery(target,live).scan(range,new Discovery.Listener(){public void progress(int n,int total,List<Device> ds){}public void finished(List<Device> ds,boolean complete,String message){result[0]=ds;summary[0]=message;finished.countDown();}});
        check(finished.await(FULL_SCAN_SECONDS,TimeUnit.SECONDS),"Live scan completes: "+range);Device found=null;for(Device d:result[0])if(d.ip.equals(expected))found=d;
        if(found==null&&!self&&Build.VERSION.SDK_INT<=28){
            IcmpEcho.Result denied=IcmpEcho.probe(()->AndroidIcmp.open(live,InetAddress.getByName(expected)),()->false,300,2,120);
            check(denied.status==IcmpEcho.Status.ERROR&&(denied.problem==IcmpEcho.Problem.PERMISSION||denied.problem==IcmpEcho.Problem.UNSUPPORTED),"An absent legacy gateway is explained by independently confirmed platform ICMP restrictions");
            ScanReport report=new Store(target).report(live.key);check(report!=null&&!report.complete&&report.sources.getOrDefault("ICMP echo","").startsWith("Failed"),"Legacy platform restrictions stay visible as Partial rather than inventing a gateway response");
            Bundle platform=new Bundle();platform.putString("stream","PLATFORM: gateway produced no qualifying TCP response; app ICMP unavailable: "+denied.problem+". Verified honest absence and Partial status.\n");sendStatus(0,platform);return;
        }
        check(found!=null,"Live "+(self?"self":"non-self gateway")+" response found: "+expected+" / "+summary[0]);check(found.self==self,"Live endpoint self classification");if(!self)check(!found.evidence.isEmpty(),"Non-self endpoint has response evidence");
    }
